sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var jsonObj = api.data.equipment_type.output;
    var numOfEquip = jsonObj.data.GlideAggregate_Query.length;
    var resArr = [];
    for (var i = 0; i < numOfEquip; i++) {
        var elem = {
            id: jsonObj.data.GlideAggregate_Query[i].groupBy[0].value.toString(),
            label: jsonObj.data.GlideAggregate_Query[i].groupBy[0].displayValue.toString()
        } ; 
        resArr.push(elem); 
    }
    console.log(resArr) ; 
    return JSON.stringify(resArr);
}
